    col_dividers = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]

    def spans(size, dividers):
        parts = []
        start = 0
        for d in dividers:
            if start < d:
                parts.append((start, d))
            start = d + 1
        if start < size:
            parts.append((start, size))
        return parts

    rows = spans(h, row_dividers)
    cols = spans(w, col_dividers)

    # Find marker colors at the level of the grid's rectangular cells.
    markers = {}
    for ri, (r0, r1) in enumerate(rows):
        for ci, (c0, c1) in enumerate(cols):
            for r in range(r0, r1):
                for c in range(c0, c1):
                    color = grid[r][c]
                    if color not in (0, 8):
                        markers.setdefault(color, set()).add((ri, ci))

    # Record all cells traversed by each straight segment joining aligned
    # markers of the same color.
    strokes = {}
    for color, points in markers.items():
        points = list(points)
        for i, (r1, c1) in enumerate(points):
            for r2, c2 in points[i + 1:]:
                if r1 == r2:
                    for c in range(min(c1, c2), max(c1, c2) + 1):
                        strokes.setdefault((r1, c), set()).add(color)
                elif c1 == c2:
                    for r in range(min(r1, r2), max(r1, r2) + 1):
                        strokes.setdefault((r, c1), set()).add(color)

    # Preserve any marker that is not part of an aligned pair.
    for color, points in markers.items():
        for cell in points:
            strokes.setdefault(cell, set()).add(color)

    out = [row[:] for row in grid]
